AND emp.name LIKE CONCAT('%', #{empQueryParam.name}, '%')
AND emp.gender = #{empQueryParam.gender}
AND emp.entry_date >= #{empQueryParam.begin}
AND emp.entry_date <= #{empQueryParam.end}
ORDER BY emp.update_time DESC

